export function cost(key,country,quantity=1,share=1,unitOverride=null){
  const seed=P[key];let item;
  if(seed){const value=seed[country==='SG'?1:0];item={...price('food',country),id:key,label:L(seed[2],seed[3]),typical:value,min:Math.round(value*.7),max:Math.round(value*1.6),category:key};}else item=price(key,country);
  return {...item,typical:unitOverride??item.typical,quantity,simulationShare:share,sourceUrl:null,lastVerified:null,assumptions:L('Independent country simulation assumption; not a verified provider quote.','各国独立模拟假设，并非已核实的供应商报价。')};
}
export const marketTotal=items=>Math.round(items.reduce((n,i)=>n+(i.quote??i.typical)*i.quantity,0)*100)/100;
export const virtualTotal=items=>Math.round(items.reduce((n,i)=>n+(i.quote??i.typical)*i.quantity*(i.simulationShare??1),0)*100)/100;
const option=(id,title,description,items,effects={},future=L('Your choices carry into the next part of this virtual life.','你的选择将延续到下一段虚拟生活。'))=>({id,title,description,items,effects,future});
const chapter=(code,title,intro,scene,options,extra={})=>({code,title,intro,scene,options,category:'milestone',kind:'main',month:1,dialogue:L('“What would you choose, if this were another version of your life?”','“如果这是另一种人生，你会怎样选择？”'),...extra});
const carOptions=(s,index)=>{
  const c=s.country,C=(...a)=>cost(a[0],c,...a.slice(1)),owned=s.v2.assets.car;
  if(index===0)return [option('new',L('Explore a new compact car','看看全新紧凑型车'),L('A different virtual model, with a different quoted price. No real purchase is needed.','不同虚拟车型有不同报价，不需要真实购车。'),[C('bus')],{flags:{vehicleChoice:'new'}},L('A new vehicle has a warranty in this simulation.','本模拟中的新车享有保修。')),option('used',L('Explore a used compact car','看看二手紧凑型车'),L('A lower-priced used model brings an inspection decision later.','较低价格的二手车型，稍后会有检查决定。'),[C('bus')],{flags:{vehicleChoice:'used'}},L('The existing vehicle condition is selected once, independently of inspection.','既有车况只选择一次，与是否检查无关。'))];
  if(index===1)return [option('steady',L('Keep the everyday route','保留日常路线'),L('Picture the fuel and parking that come with this virtual routine.','想象此虚拟日常中的能源和停车开支。'),[C('fuel'),C('parking')]),option('shared',L('Combine trips with a neighbour','与邻居合并出行'),L('Half as many optional journeys; the unit fuel estimate is unchanged.','可选出行减少一半，能源单价不变。'),[C('fuel',.5),C('parking')],{flags:{sharedRoutes:true}},L('Future fuel use is lower because you drive less, not because prices change.','未来能源用量因里程减少而降低，并非价格改变。'))];
  if(index===2)return [option('inspect',L('Look beneath the bonnet','打开引擎盖看看'),L('Pay for an independent inspection. It can reveal an existing defect; it does not create one.','安排独立检查，可能揭示已有故障，但不会造成故障。'),[C('inspection')],{flags:{inspectedCar:true}}),option('skip',L('Use the seller’s information','依赖卖家资料'),L('Skip the inspection fee; a pre-existing defect can remain hidden.','省下检查费，已有故障可能仍未发现。'),[],{flags:{inspectedCar:false}})];
  if(index===3)return [option('covered',L('Choose comprehensive coverage','选择综合保障'),L('Keep a policy-specific virtual cover allowance.','保留依保单而定的虚拟保障预算。'),[C('vehicleInsurance')],{flags:{coverage:'comprehensive'}},L('Some covered events may use a policy excess instead of the whole repair quote.','某些受保事件可能只需虚拟自付额，而非全额维修报价。')),option('thirdParty',L('Choose third-party coverage','选择第三者保障'),L('A distinct, narrower policy illustration. Own damage is not assumed covered.','不同且较窄的保障模拟，不假定自己的损坏获保。'),[C('vehicleInsuranceThird')],{flags:{coverage:'thirdParty'}},L('Own damage remains a virtual liability.','自身车辆损坏仍是虚拟责任。'))];
  if(index===4){const used=s.v2.flags.vehicleChoice==='used',key=used?'carUsed':'carNew',share=c==='MY'?.2:.4;return [option('collect',L('Collect your virtual keys','领取虚拟车钥匙'),L('Only the down-payment share is a virtual expense today. The market value and remaining virtual loan stay separate.','今天只把首付部分记为虚拟开支。市场价值与剩余虚拟贷款分开记录。'),[C(key,1,share),C('roadTax')],{assets:{car:{condition:used?'used':'new',value:C(key).typical,principal:C(key).typical*(1-share),warranty:!used}},lifeStage:'vehicle-owner'},L('Instalments, fuel, renewals and repairs follow ownership. Your real funds never buy this car.','供款、能源、续保与维修会随着拥车而来。真实资金不会购买此车。'))];}
  const instalment=cost('instalment',c,1,1,carCosts(s.config).monthly);
  if(index===11||index===23)return [option('renew',L('Renew the virtual policy','续保虚拟保单'),L('An annual payment, not a second copy of a monthly provision.','这是一笔年度付款，不会重复计算每月准备金。'),[C(s.v2.flags.coverage==='thirdParty'?'vehicleInsuranceThird':'vehicleInsurance'),C('roadTax')])];
  if([6,14,18].includes(index))return [option('service',L('Arrange the scheduled service','安排定期保养'),L('The same local service price applies at every savings difficulty.','无论储蓄难度如何，同一本地服务价格保持不变。'),[C('maintenance'),C('coffee')]),option('serviceOnly',L('Service without optional extras','保养但不选额外服务'),L('Keep the necessary service; skip the optional café stop.','保留必要保养，不安排可选咖啡馆停留。'),[C('maintenance')],{flags:{frugal:true}})];
  return [option('routine',L('Keep the current routine','保留当前习惯'),L('A virtual instalment and the fuel you use.','一笔虚拟供款，加上实际模拟用量的能源。'),[instalment,C('fuel',s.v2.flags.sharedRoutes?.5:1),C('parking')]),option('fewerTrips',L('Plan fewer optional trips','减少可选出行'),L('Use half the usual fuel quantity; loan payments do not shrink.','能源用量减半，贷款供款不会缩小。'),[instalment,C('fuel',.5),C('parking')],{flags:{sharedRoutes:true,frugal:true}})];
};
function babyChapters(s){return chaptersFor('baby',s.country,s.config).map((c,index)=>{
  const C=(k,q=1,share=1)=>{const twin=s.v2.flags.twins;let mult=1;if(twin){if(['diapers','wipes','milk','clothes','food','learning','cot','seat','childcare','preschool'].includes(k))mult=2;else if(['consult','care','screen','delivery','postpartum','stroller','health'].includes(k))mult=1.35;}return cost(k,s.country,q*mult,share,s.config[k]??null);};
  const share=index===6?.3:index===8?.7:1,items=c.keys.map(k=>C(k,1,share));
  let options=[option('essentials',L('Choose the thoughtful essentials','选择用心准备的必需品'),L('Keep the quoted essentials in this fictional household.','为这个虚构家庭保留报价中的必需品。'),items)];
  if(index===0)options.push(option('pack',L('Choose a two-test pack','选择双份测试装'),L('A different product pack, with a separate fixed estimate. Nothing is confirmed yet.','不同产品组合采用独立固定估价，目前尚未确认。'),[C('testPack')]));
  else if(index===1)options[0]={...options[0],title:L('Welcome this virtual beginning','迎接这个虚拟开始'),effects:{lifeStage:'expecting',flags:{pregnancyConfirmed:true}}};
  else if(index===5||index===7)options.push(option('reuse',L('Reuse suitable non-safety essentials','复用适用的非安全关键用品'),L('Reuse selected furniture or clothing. Required care and safety equipment remain included.','复用部分家具或衣物，保留必要照护及安全设备。'),items.filter(i=>!['nursery','clothes','cot'].includes(i.id)),{flags:{nurseryReused:true,frugal:true}},L('The nursery scene evolves with fewer new purchases.','婴儿房随着较少的新购物品逐渐成形。')));
  else if(index>=9)options.push(option('family',L('Share childcare with family','与家人分担托育'),L('Model half a month of paid childcare alongside family help. Healthcare prices stay unchanged.','在家人帮助下模拟半个月付费托育，医疗单价不变。'),items.map(i=>['childcare','preschool'].includes(i.id)?{...i,quantity:i.quantity*.5}:i),{flags:{familyCare:true,frugal:true}},L('Family help reduces the quantity of paid care, not the price of the same service.','家庭帮助减少付费照护数量，而非相同服务单价。')));
  return chapter(`baby-${index}`,c.title,c.intro,c.scene,options,{month:c.month,act:c.act,category:[0,2,3,4].includes(index)?'everyday':'milestone',dialogue:index===1?(s.v2.flags.twins?L('“Two little heartbeats in this story. We can take it one step at a time.”','“故事里有两个小心跳。我们可以一步一步来。”'):L('“A new chapter, and plenty of time to learn.”','“新的篇章，也有足够时间慢慢学习。”')):L('“Every ordinary act of care is part of the story.”','“每一份日常照顾，都是故事的一部分。”')});
});}
