export function mainChapters(s){
  if(s.story==='baby')return babyChapters(s);
  if(s.story==='car')return chaptersFor('car',s.country,s.config).map((c,i)=>chapter(`car-${i}`,c.title,c.intro,c.scene,carOptions(s,i),{month:i+1,act:c.act,category:[0,2,3,4].includes(i)?'milestone':'everyday'}));
  if(s.story==='travel')return chaptersFor('travel',s.country,s.config).map((c,i)=>{const items=c.keys.map(k=>cost(k,s.country,k==='hotel'?1:s.config.travellers||1,1,s.config.budget?.[k]??null));return chapter(`travel-${i}`,c.title,c.intro,c.scene,[option('planned',L('Keep the planned experience','保留计划体验'),L('Keep the items in this virtual trip.','保留虚拟旅行中的项目。'),items,{lifeStage:i>=5?'travelling':'preparing-trip'}),option('simple',L('Leave out optional shopping','不安排可选购物'),L('Food and transport remain; optional shopping is removed as a separate item.','保留餐饮与交通，独立移除可选购物。'),items.filter(i=>i.id!=='shopping'),{flags:{frugal:true}})],{month:i+1,act:c.act,category:i===6?'minor':'milestone'});});
  return (definitions[s.story]||[]).map(([en,zh,introEn,introZh,scene,rows],i)=>{
    const options=rows.map(([id,en,zh,keys,flags])=>option(id,L(en,zh),L('Choose the scope of this virtual incident. Market unit prices stay fixed.','选择虚拟事件的范围，市场单价保持不变。'),keys.map(k=>cost(k,s.country)),{flags}));
    if(s.story==='home'&&i===3){const value=cost(s.v2.flags.propertyType==='subsale'?'propertySubsale':'propertyNew',s.country);options[0].items=[{...value,simulationShare:s.country==='MY'?.1:.25}];options[0].effects.assets={property:{type:s.v2.flags.propertyType||'new',value:value.typical,renovation:'empty'}};options[0].effects.lifeStage='homeowner';}
    if(s.story==='wedding'&&(i===2||i===5))options[0].items.push(cost(s.v2.flags.weddingStyle==='large'?'venueLarge':'venueSmall',s.country,1,i===2?.3:.7));
    if(s.story==='education'&&(i===1||i===4))options[0].items.push(cost('course',s.country,1,i===1?.3:.7));
    if(s.story==='living'&&[0,1,3].includes(i))for(const o of options)o.items.push(cost('rentHome',s.country,(i===0?(o.id==='room'?.5:1):s.v2.flags.rentShare||1)*(i===1?2:1),1));
    return chapter(`${s.story}-${i}`,L(en,zh),L(introEn,introZh),scene,options,{month:(s.story==='home'?[1,3,6,12,18,24,30]:s.story==='retirement'?[1,12,36,60,120,240]:[1,2,4,6,9,12])[i]||i+1,act:Math.min(4,i),category:i===0||i===3?'milestone':'everyday'});
  });
}
export function interludes(s){const C=k=>cost(k,s.country);const list=[
chapter('rain-walk',L('The sky has other plans','天空另有打算'),L('Halfway through an ordinary walk, the first drops land on your sleeve.','平常散步到一半，第一滴雨落在袖子上。'),'rain',[option('umbrella',L('Find a sturdy umbrella','找把结实雨伞'),L('Buy a new item in the virtual town.','在虚拟小镇添置新用品。'),[C('umbrella')]),option('bus',L('Catch the bus home','乘巴士回家'),L('A different service, with its own fixed local estimate.','不同服务，采用独立本地估价。'),[C('bus')],{flags:{frugal:true}})],{kind:'interlude',category:'everyday',probability:1,cooldown:4,max:4}),
chapter('quiet-kettle',L('A quiet kettle','安静的水壶'),L('The kitchen is ready for tea. The kettle has other ideas.','厨房已准备泡茶，水壶却有了其他想法。'),'kitchen',[option('repair',L('Repair the kettle','维修水壶'),L('Use a repair service instead of buying a new product.','使用维修服务，而非购买新产品。'),[C('repairKettle')],{flags:{frugal:true}}),option('replace',L('Choose a replacement','选择更换'),L('A new kettle has a different market estimate.','新水壶有不同市场估价。'),[C('kettle')])],{kind:'interlude',category:'minor',probability:.7,cooldown:5,max:2}),
chapter('neighbour-picnic',L('A note from next door','来自隔壁的纸条'),L('A neighbour invites you to make an ordinary afternoon a little special.','邻居邀请你，让平常的下午多一点特别。'),'picnic',[option('picnic',L('Bring a basket for the picnic','带一篮野餐用品'),L('Choose shared supplies.','选择共享用品。'),[C('picnic')]),option('coffee',L('Meet over one café drink','喝杯咖啡聊聊'),L('Choose a smaller, different outing.','选择另一种较小的外出。'),[C('coffee')],{flags:{frugal:true}})],{kind:'interlude',category:'everyday',probability:1,cooldown:3,max:4})];
if(s.v2.assets.car)list.push(chapter('car-battery',L('A reluctant start','不太情愿的启动'),L('Your virtual car will not start. An inspection did not cause this battery to age.','虚拟汽车无法启动，检查并没有造成电池老化。'),'car-battery',[option('replace',L('Replace the battery','更换电池'),L('The battery is a separate consumable in this simulation.','电池在此模拟中是独立耗材。'),[C('batteryCar')])],{kind:'interlude',category:'minor',probability:.5,cooldown:8,max:1}),chapter('car-tyre',L('A little wobble','一点颠簸'),L('A tyre needs attention before the next virtual journey.','下次虚拟出行前，轮胎需要处理。'),'car-tyre',[option('replace',L('Replace the tyre pair','更换一对轮胎'),L('Use the itemised replacement allowance.','使用列明的更换预算。'),[C('tyreCar')])],{kind:'interlude',category:'minor',probability:.35,cooldown:8,max:1}));
if(s.v2.assets.car&&s.v2.rolls.carDefect)list.push(chapter('car-existing-defect',L('A sound beneath the bonnet','引擎盖下的声音'),L('The defect selected for this virtual vehicle now needs a response. Your warranty changes the cost, not whether the defect exists.','这辆虚拟车已确定的故障需要处理。保修改变费用，而非故障是否存在。'),'car-repair',[option('repair',L('Resolve the existing fault','处理已有故障'),L('Use the configured warranty where applicable.','适用时使用设定的保修。'),[s.v2.assets.car.warranty?cost('carRepair',s.country,1,0):C('carRepair')])],{kind:'interlude',category:'minor',probability:1,cooldown:99,max:1}));
if(s.v2.assets.car)list.push(chapter('car-flood',L('Water across the road','路上的积水'),L('A rare virtual flood event tests the coverage you selected earlier. No real emergency savings are withdrawn.','一次罕见虚拟水灾考验先前选择的保障，不会扣减真实应急储蓄。'),'rain',[option('coverage',L('Use the selected coverage','使用已选保障'),L('A covered scenario uses an illustrative policy excess; third-party-only coverage leaves the repair allowance.','受保情景采用模拟自付额，只有第三者保障时保留维修预算。'),[C(s.v2.flags.coverage==='comprehensive'?'claimExcess':'floodRepair')])],{kind:'interlude',category:'rare',probability:.01,cooldown:99,max:1}));
if(s.v2.assets.property&&s.v2.rolls.homeDefect)list.push(chapter('home-leak',L('A mark on the ceiling','天花板上的痕迹'),L('A persisted hidden defect becomes visible. Inspection could have revealed it earlier; skipping inspection did not create it.','已保存的隐患变得可见，检查可能更早发现它，但跳过检查并未造成它。'),'renovation',[option('repair',L('Arrange the leak repair','安排漏水维修'),L('Keep a separate repair quotation.','保留独立维修报价。'),[C('leak')])],{kind:'interlude',category:'minor',probability:1,cooldown:99,max:1}));
return list;
}
